r.wms_tenant_id = #{wmsTenantId}
AND r.fee_type = 'SHIPPING'

    AND r.bill_month >= #{monthStart}


    AND r.bill_month <= #{monthEnd}


    AND r.erp_tenant_id = #{erpTenantId}

mapper.select:
SELECT r.id, r.bill_month AS billMonth, r.logistics_product_id AS productId, COALESCE(NULLIF(r.product_name_snapshot, ''), p.product_name, '已删除产品') AS productName, r.product_name_snapshot AS productNameSnapshot, r.product_description_snapshot AS productDescriptionSnapshot, t.tenant_name AS ownerName, COALESCE(f.fulfillment_no, o.outbound_no, f.source_order_no, r.biz_id) AS businessNo, f.source_order_no AS platformOrderId, r.tracking_no AS trackingNo, r.amount, r.currency AS currency, DATE_FORMAT(r.create_time, '%Y-%m-%d %H:%i:%s') AS createTime FROM wms_client_billing_record r LEFT JOIN sys_tenant t ON t.id = r.erp_tenant_id LEFT JOIN wms_logistics_product p ON p.id = r.logistics_product_id LEFT JOIN wms_fulfillment_order f ON f.id = r.fulfillment_order_id LEFT JOIN wms_sales_outbound_order o ON o.id = r.outbound_order_id
AND r.logistics_product_id = #{productId}
ORDER BY r.id DESC
